import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
B="http://localhost:8080"
tok=None
log={}
def newtok():
    global tok
    r=urllib.request.Request(B+"/token",method="POST",data=b"")
    tok=json.load(urllib.request.urlopen(r))["token"]
def get(path):
    global tok
    for attempt in range(200):
        if tok is None: newtok()
        r=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
        try:
            with urllib.request.urlopen(r) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            body=e.read().decode()[:200]
            log.setdefault((e.code,body[:80]),0); log[(e.code,body[:80])]+=1
            if e.code==404: return None
            if e.code==401: tok=None; continue
            if e.code==429:
                ra=e.headers.get("Retry-After")
                try: w=float(ra)
                except: 
                    try: w=float(json.loads(body).get("retry_after",1))
                    except: w=1
                time.sleep(w+0.1); continue
            time.sleep(1)
        except Exception as e:
            log.setdefault(("exc",repr(e)[:80]),0); log[("exc",repr(e)[:80])]+=1
            time.sleep(1)
    raise RuntimeError(path)
orders=[];page=1;total=None
while True:
    d=get(f"/orders?page={page}")
    total=d["total_pages"]; orders+=d["items"]
    if not d["next"]: break
    page+=1
print("pages",page,"total_pages",total,"listings",len(orders))
seen={};dups=0;conflicts=0
for o in orders:
    if o["id"] in seen:
        dups+=1
        if seen[o["id"]]!=o: conflicts+=1
    else: seen[o["id"]]=o
print("distinct",len(seen),"dups",dups,"conflicting dups",conflicts)
from collections import Counter
print(Counter(o["status"] for o in seen.values()))
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
q=[]
for o in seen.values():
    if o["status"]!="shipped": continue
    dt=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if dt.tzinfo is None: print("naive",o)
    if lo<=dt.astimezone(timezone.utc)<hi: q.append(o)
cust={}
for o in q:
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
missing=[c for c,v in cust.items() if v is None]
print("qualifying",len(q),"customers",len(cust),"missing",missing)
reg={"north":0,"south":0,"east":0,"west":0}
for o in q:
    c=cust[o["customer_id"]]
    a=o["amount_cents"]*(100-c["discount_pct"])
    reg[c["region"]]+=(a+50)//100
tot=sum(reg.values())
res={"total_cents":tot,"order_count":len(q),"duplicates_skipped":dups,"by_region":reg}
json.dump(res,open("/workspace/result.json","w"),indent=2)
print(res); print(log)
EOF
